import java.util.Date;
class SealedSession {
    private final Date loginTime;
    public SealedSession(Date time) {
        this.loginTime = new Date(time.getTime());
    }
    public Date getLoginTime() {
        return new Date(loginTime.getTime());
    }
}
public class SessionApp {
    public static void main(String[] args) {
        Date d = new Date(500L);
        SealedSession s = new SealedSession(d);
        d.setTime(999L);
        s.getLoginTime().setTime(888L);
        System.out.println(s.getLoginTime().getTime());
    }
}
