import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
class SafeRegistry {
    private final List<StringBuilder> list;
    public SafeRegistry(List<StringBuilder> input) {
        this.list = Collections.unmodifiableList(new ArrayList<>(input));
    }
    public List<StringBuilder> getList() { return list; }
}
public class RegistryApp {
    public static void main(String[] args) {
        List<StringBuilder> orig = new ArrayList<>();
        orig.add(new StringBuilder("A"));
        SafeRegistry reg = new SafeRegistry(orig);
        reg.getList().get(0).append("B");
        System.out.println(reg.getList().get(0).toString());
    }
}
```

